def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    rich_threats = 0
    urgent_opps = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= 180:
                rich_threats += 1
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opps += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))

    if not alive:
        return max(0.0, min(budget, 18.0))

    high_supply = supply >= 22
    low_supply = supply <= 17

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1

    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 2

    if low_supply:
        danger += 2
    elif not high_supply:
        danger += 1

    if day >= 8:
        danger += 1

    market_hot = highest_prev >= 120 or avg_prev >= 100

    if danger >= 6:
        target = max(118.0, highest_prev + 3.0)
    elif danger >= 4:
        target = max(92.0, avg_prev + 4.0, highest_prev * 0.93)
    elif danger >= 2:
        if high_supply and market_hot:
            target = 46.0
        else:
            target = max(62.0, avg_prev * 0.72)
    else:
        if high_supply:
            target = 28.0 if rich_threats >= 2 else 22.0
        else:
            target = 40.0

    if urgent_opps >= 2 and not high_supply:
        target += 8.0
    elif urgent_opps == 1 and low_supply:
        target += 4.0

    if budget < target:
        if danger >= 4:
            return max(0.0, budget)
        return max(0.0, min(budget, target * 0.75))

    reserve_floor = 0.0
    if day <= 7:
        reserve_floor = DAILY_SALARY * (10 - day) * 0.18
    if budget - target < reserve_floor and danger < 5:
        target = max(0.0, budget - reserve_floor)

    target = min(target, budget)
    if target < 0:
        target = 0.0
    return float(target)

