def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp in opponents_status.values():
        if opp.get('alive', False):
            alive_opps.append(opp)

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from immediate previous_trace only
    prev_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    avg_prev_bid = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    # Infer pressure: if others bid high yesterday, we need to secure water.
    # Aggressive baseline to beat mid pack while not exhausting budget.
    pressure = 0.0
    if highest_prev_bid > 0:
        pressure = min(1.0, highest_prev_bid / (DAILY_SALARY * 1.3))

    # Supply effect: with lower supply, competition is higher; bid slightly more.
    # supply_range meta: 15..25
    if supply <= 0:
        supply_factor = 1.0
    else:
        supply_factor = 1.0 + (25.0 - min(25.0, max(15.0, supply))) / 20.0  # ~1.0..1.5

    # Health urgency: if we are close to danger, bid harder.
    if my_hp <= 2:
        hp_factor = 1.25
    elif my_hp <= 4:
        hp_factor = 1.10
    else:
        hp_factor = 0.95

    # If we've already gone without water, urgency increases.
    if my_no_water_days >= 2:
        no_water_factor = 1.15
    else:
        no_water_factor = 1.0

    # Target bid: anchor around a fraction of yesterday highest/average plus a pressure premium.
    # Use int() only where indexing would matter; here just compute floats.
    target = 0.0
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # Others were very aggressive; match mid-high.
        target = max(avg_prev_bid * 0.85, highest_prev_bid * 0.55)
    else:
        # Lower pressure; still bid enough to avoid being outbid.
        target = max(avg_prev_bid * 0.75, DAILY_SALARY * 0.55)

    target *= (0.9 + 0.25 * pressure)
    target *= supply_factor
    target *= hp_factor
    target *= no_water_factor

    # Keep within budget and avoid overbidding beyond a reasonable cap.
    # Cap: don't exceed ~1.4x daily salary unless budget forces it.
    cap = DAILY_SALARY * 1.4
    bid = min(my_budget, cap, target)

    # Ensure non-trivial bid so we don't repeat Cindy-like 0-bid behavior.
    min_bid = DAILY_SALARY * 0.25
    if my_budget < min_bid:
        min_bid = 0.0

    bid = max(min_bid, bid)

    # Final safety
    if bid < 0.0:
        bid = 0.0
    return float(bid)
